#include "ed448.h"
#include "ed448base.h"

/* \cond NO_DOCUMENT */

/*! \typedef ed448_point
 * \brief Private extended Edwards point with X*Y = Z*T.
 */
typedef struct
{
	/*! X coordinate. */
	ed448_fe x;
	/*! Y coordinate. */
	ed448_fe y;
	/*! Projective denominator Z. */
	ed448_fe z;
	/*! Extended coordinate T = X*Y/Z. */
	ed448_fe t;
} ed448_point;

/*! \typedef ed448_affine
 * \brief Private affine point with precomputed d*x*y.
 */
typedef struct
{
	/*! X coordinate. */
	ed448_fe x;
	/*! Y coordinate. */
	ed448_fe y;
	/*! Affine product d*x*y. */
	ed448_fe td;
} ed448_affine;

